/bin/bash -lc "cat <<'EOF' > app/blog/[id]/page.tsx
import type { Metadata } from 'next';
import Link from 'next/link';
import { notFound } from 'next/navigation';
import { cache } from 'react';

type Post = {
  id: number;
  title: string;
  body: string;
};

type Comment = {
  id: number;
  name: string;
  body: string;
  email: string;
};

type PageProps = {
  params: {
    id: string;
  };
};

export const revalidate = 300;
export const dynamicParams = true;

const getPost = cache(async (id: string): Promise<Post | null> => {
  const response = await fetch(
    "'`https://jsonplaceholder.typicode.com/posts/${id}`,
    { next: { revalidate: 300 } }
  );

  if (!response.ok) {
    return null;
  }

  const post = (await response.json()) as Post;

  if (!post?.id) {
    return null;
  }

  return post;
});

const getComments = cache(async (id: string): Promise<Comment[]> => {
  const response = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: 300 } }
  );

  if (!response.ok) {
    return [];
  }

  return (await response.json()) as Comment[];
});

function buildDescription(text: string): string {
  if (text.length <= 160) {
    return text;
  }
  return text.substring(0, 160);
}

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const response = await fetch('"'https://jsonplaceholder.typicode.com/posts', {
    next: { revalidate: 300 },
  });

  if ("'!response.ok) {
    return [];
  }

  const posts = (await response.json()) as Post[];
  return posts.slice(0, 10).map((post) => ({ id: String(post.id) }));
}

export async function generateMetadata({
  params,
}: PageProps): Promise<Metadata> {
  const post = await getPost(params.id);

  if (!post) {
    return {
      title: '"'Post Not Found - My Blog',
    };
  }

  const description = buildDescription(post.body);

  return {
    title: "'`${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  };
}

export default async function BlogPostPage({ params }: PageProps) {
  const post = await getPost(params.id);

  if (!post) {
    notFound();
  }

  const comments = await getComments(params.id);

  return (
    <article>
      <Link className="button-link" href="/blog">
        ← Back to Blog
      </Link>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}
