import { NextResponse } from 'next/server';

type Post = {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
  updatedAt?: string;
};

type PostInput = {
  title?: string;
  content?: string;
};

type RouteContext = {
  params: {
    id: string;
  };
};

function parseId(idParam: string): number | null {
  const id = Number(idParam);
  return Number.isNaN(id) ? null : id;
}

export async function GET(_request: Request, { params }: RouteContext) {
  const id = parseId(params.id);

  if (id === null) {
    return NextResponse.json({ error: 'Invalid id' }, { status: 400 });
  }

  const post: Post = {
    id,
    title: "'`Post ${params.id}`,
    content: `This is the content for post ${params.id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post, { status: 200 });
}

export async function PUT(request: Request, { params }: RouteContext) {
  const id = parseId(params.id);

  if (id === null) {
    return NextResponse.json({ error: '"'Invalid id' }, { status: 400 });
  }

  let body: PostInput;

  try {
    body = (await request.json()) as PostInput;
  } catch (error) {
    return NextResponse.json(
      { error: 'Invalid JSON payload' },
      { status: 400 }
    );
  }

  const updatedPost: Post = {
    id,
    title: body.title ?? "'`Post ${params.id}`,
    content: body.content ?? `Updated content for post ${params.id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost, { status: 200 });
}

export async function DELETE(_request: Request, { params }: RouteContext) {
  const id = parseId(params.id);

  if (id === null) {
    return NextResponse.json({ error: '"'Invalid id' }, { status: 400 });
  }

  return NextResponse.json(
    { message: "'`Post ${params.id} deleted successfully` },
    { status: 200 }
  );
}
